package cn.grad.attendance;

import static cn.grad.attendance.Domain.*;
import jakarta.servlet.http.*;
import java.time.*;
import java.util.*;
import org.springframework.beans.factory.annotation.Value;
import org.springframework.http.ResponseCookie;
import org.springframework.security.crypto.password.PasswordEncoder;
import org.springframework.transaction.annotation.Transactional;
import org.springframework.web.bind.annotation.*;

@RestController @RequestMapping("/api/v1")
public class ManagementController {
    private final Store store;private final AuthController auth;private final AttendanceService attendance;private final PasswordEncoder passwords;private final boolean secure;
    public ManagementController(Store store,AuthController auth,AttendanceService attendance,PasswordEncoder passwords,@Value("${app.secure-cookie}") boolean secure) {this.store=store;this.auth=auth;this.attendance=attendance;this.passwords=passwords;this.secure=secure;}
    @GetMapping("/departments") Object departments(@RequestParam(defaultValue="0") int page,@RequestParam(defaultValue="100") int size) {return Api.ok(Api.page(store.list(Department.class,"order by e.id"),page,size));}
    @PostMapping("/departments") @Transactional Object addDepartment(@RequestBody Map<String,Object> body) {attendance.guard();var d=new Department();d.name=Api.required(body,"name",100);store.save(d);attendance.audit(auth.admin().id,"CREATE_DEPARTMENT",d.id.toString(),d.name);return Api.ok(d);}
    @PutMapping("/departments/{id}") @Transactional Object editDepartment(@PathVariable Long id,@RequestBody Map<String,Object> body) {attendance.guard();var d=store.get(Department.class,id);d.name=Api.required(body,"name",100);d.active=Api.bool(body,"active",true);attendance.audit(auth.admin().id,"UPDATE_DEPARTMENT",id.toString(),d.name);return Api.ok(d);}
    @GetMapping("/employees") Object employees(@RequestParam(defaultValue="0") int page,@RequestParam(defaultValue="20") int size,@RequestParam(required=false) String keyword,@RequestParam(required=false) Long departmentId) {return Api.ok(Api.page(store.list(Employee.class,"order by e.id desc").stream().filter(e->departmentId==null||departmentId.equals(e.departmentId)).filter(e->keyword==null||e.name.contains(keyword)||e.employeeNo.contains(keyword)).map(this::employeeView).toList(),page,size));}
    @PostMapping("/employees") @Transactional Object createEmployee(@RequestBody Map<String,Object> body) {
        var settings=attendance.guard();if(store.list(Employee.class,"where e.active=true").size()>=100)throw Api.error(400,"EMPLOYEE_LIMIT","第一版最多100名在职员工");
        var e=new Employee();e.employeeNo=Api.required(body,"employeeNo",50);e.name=Api.required(body,"name",100);e.departmentId=Api.number(body,"departmentId");if(e.departmentId==null||!store.get(Department.class,e.departmentId).active)throw Api.error(400,"INVALID_DEPARTMENT","请选择有效部门");
        e.startDate=body.get("startDate")==null?attendance.today():LocalDate.parse(body.get("startDate").toString());if(e.startDate.isBefore(attendance.today().minusDays(365))||e.startDate.isAfter(attendance.today()))throw Api.error(400,"INVALID_DATE","建档入职日期须在过去365天至今天之间");
        store.save(e);String initial=body.get("password")==null?"Init9-"+Crypto.token().substring(0,14):body.get("password").toString();AuthController.validatePassword(initial);
        var u=new UserAccount();u.username=body.get("username")==null?e.employeeNo:Api.required(body,"username",100);u.passwordHash=passwords.encode(initial);u.employeeId=e.id;u.role=body.getOrDefault("role","EMPLOYEE").toString();if(!Set.of("ADMIN","EMPLOYEE").contains(u.role))throw Api.error(400,"INVALID_ROLE","角色不正确");store.save(u);
        attendance.audit(auth.admin().id,"CREATE_EMPLOYEE",e.id.toString(),"建档并创建账号，角色="+u.role);var result=employeeView(e);result.put("initialPassword",initial);result.put("username",u.username);return Api.ok(result);
    }
    @PutMapping("/employees/{id}") @Transactional Object editEmployee(@PathVariable Long id,@RequestBody Map<String,Object> body) {
        var settings=attendance.guard();var e=store.get(Employee.class,id);
        boolean active=Api.bool(body,"active",e.active);if(!e.active&&active)throw Api.error(400,"EMPLOYMENT_HISTORY","为保留历史在职区间，离职重入请新建工号档案");
        if(body.containsKey("startDate")&&!e.startDate.toString().equals(body.get("startDate").toString()))throw Api.error(400,"IMMUTABLE_START_DATE","建档后不能修改入职日期");
        if(body.containsKey("employeeNo")&&!e.employeeNo.equals(body.get("employeeNo")))throw Api.error(400,"IMMUTABLE_EMPLOYEE_NO","建档后不能修改工号");
        if(body.containsKey("name"))e.name=Api.required(body,"name",100);
        if(body.containsKey("departmentId")){Long dep=Api.number(body,"departmentId");if(!store.get(Department.class,dep).active)throw Api.error(400,"INVALID_DEPARTMENT","部门已停用");e.departmentId=dep;}
        if(!active&&e.active){if(Objects.equals(auth.current().employeeId,e.id))throw Api.error(400,"SELF_DISABLE","不能停用自己的档案");e.active=false;e.endDate=attendance.today();settings.galleryVersion++;invalidateSessions("人员库已变更");}
        attendance.audit(auth.admin().id,"UPDATE_EMPLOYEE",id.toString(),"active="+e.active);return Api.ok(employeeView(e));
    }
    Map<String,Object> employeeView(Employee e) {var m=new LinkedHashMap<String,Object>();m.put("id",e.id);m.put("employeeNo",e.employeeNo);m.put("name",e.name);m.put("departmentId",e.departmentId);m.put("departmentName",store.get(Department.class,e.departmentId).name);m.put("active",e.active);m.put("startDate",e.startDate);m.put("endDate",e.endDate);m.put("faceEnrolled",!store.list(FaceTemplate.class,"where e.employeeId=?1",e.id).isEmpty());return m;}
    @GetMapping("/devices") Object devices(@RequestParam(defaultValue="0") int page,@RequestParam(defaultValue="20") int size) {return Api.ok(Api.page(store.list(Device.class,"order by e.id desc").stream().map(d->Map.of("id",d.id,"name",d.name,"expiresAt",d.expiresAt,"createdAt",d.createdAt,"revoked",d.revoked)).toList(),page,size));}
    @PostMapping("/devices") @Transactional Object device(@RequestBody Map<String,Object> body,HttpServletResponse response) {attendance.guard();String token=Crypto.token();var d=new Device();d.name=Api.required(body,"name",100);d.tokenHash=Crypto.hash(token);d.expiresAt=attendance.now().plusDays(7);store.save(d);response.addHeader("Set-Cookie",ResponseCookie.from("PUNCH_DEVICE",token).httpOnly(true).secure(secure).sameSite("Strict").path("/api/v1/kiosk").maxAge(Duration.ofDays(7)).build().toString());attendance.audit(auth.admin().id,"AUTHORIZE_DEVICE",d.id.toString(),d.name);return Api.ok(Map.of("id",d.id,"name",d.name,"expiresAt",d.expiresAt));}
    @DeleteMapping("/devices/{id}") @Transactional Object revoke(@PathVariable Long id) {attendance.guard();var d=store.get(Device.class,id);d.revoked=true;for(var s:store.list(PunchSession.class,"where e.deviceId=?1 and e.status='PENDING'",id)){s.status="CANCELLED";s.resultMessage="设备授权已撤销";}attendance.audit(auth.admin().id,"REVOKE_DEVICE",id.toString(),d.name);return Api.ok(null);}
    @GetMapping("/rules") Object rules() {var result=new LinkedHashMap<String,Object>();result.put("activeRule",attendance.rule(attendance.today()));result.put("pendingRule",store.first(Rule.class,"where e.effectiveDate>?1 order by e.effectiveDate",attendance.today()).orElse(null));return Api.ok(result);}
    @PutMapping("/rules") @Transactional Object rules(@RequestBody Map<String,Object> body) {attendance.guard();LocalDate tomorrow=attendance.today().plusDays(1);var r=store.first(Rule.class,"where e.effectiveDate=?1",tomorrow).orElseGet(()->{var row=new Rule();row.effectiveDate=tomorrow;store.save(row);return row;});
        r.startTime=LocalTime.parse(Api.required(body,"startTime",20));r.endTime=LocalTime.parse(Api.required(body,"endTime",20));r.inWindowStart=LocalTime.parse(Api.required(body,"inWindowStart",20));r.inWindowEnd=LocalTime.parse(Api.required(body,"inWindowEnd",20));r.outWindowStart=LocalTime.parse(Api.required(body,"outWindowStart",20));r.outWindowEnd=LocalTime.parse(Api.required(body,"outWindowEnd",20));r.lateGraceMinutes=Integer.parseInt(body.getOrDefault("lateGraceMinutes",5).toString());r.earlyGraceMinutes=Integer.parseInt(body.getOrDefault("earlyGraceMinutes",5).toString());
        if(!r.startTime.isBefore(r.endTime)||r.inWindowStart.isAfter(r.inWindowEnd)||!r.inWindowEnd.isBefore(r.outWindowStart)||r.outWindowStart.isAfter(r.outWindowEnd)||!AttendanceEngine.inWindow(r,"IN",r.startTime)||!AttendanceEngine.inWindow(r,"OUT",r.endTime)||r.lateGraceMinutes<0||r.earlyGraceMinutes<0||r.lateGraceMinutes>60||r.earlyGraceMinutes>60)throw Api.error(400,"INVALID_RULE","仅支持固定日班：窗口不重叠，上下班须位于对应窗口，宽限0至60分钟");
        attendance.audit(auth.admin().id,"UPDATE_RULE",r.id.toString(),"从 "+tomorrow+" 生效");return Api.ok(r);}
    @GetMapping("/calendar") Object calendar(@RequestParam(required=false) LocalDate from,@RequestParam(required=false) LocalDate to,@RequestParam(defaultValue="0") int page,@RequestParam(defaultValue="100") int size) {LocalDate start=from==null?attendance.today().withDayOfMonth(1):from,end=to==null?start.plusMonths(1).minusDays(1):to;attendance.validateRange(start,end);return Api.ok(Api.page(store.list(CalendarDay.class,"where e.date>=?1 and e.date<=?2 order by e.date",start,end),page,size));}
    @PutMapping("/calendar/{date}") @Transactional Object calendar(@PathVariable LocalDate date,@RequestBody Map<String,Object> body) {attendance.guard();if(!date.isAfter(attendance.today()))throw Api.error(400,"HISTORICAL_CALENDAR","仅允许修改未来日期的工作日历");var day=store.first(CalendarDay.class,"where e.date=?1",date).orElseGet(()->{var c=new CalendarDay();c.date=date;store.save(c);return c;});day.workday=Api.bool(body,"workday",true);day.note=body.getOrDefault("note","").toString();if(day.note.length()>255)throw Api.error(400,"INVALID_INPUT","说明太长");attendance.audit(auth.admin().id,"UPDATE_CALENDAR",date.toString(),"workday="+day.workday);return Api.ok(day);}
    @GetMapping("/settings") Object settings() {return Api.ok(attendance.settings());}
    @PutMapping("/settings") @Transactional Object settings(@RequestBody Map<String,Object> body) {var s=attendance.guard();String before="liveness="+s.livenessEnabled+",threshold="+s.recognitionThreshold+",margin="+s.candidateMargin;double threshold=Double.parseDouble(body.getOrDefault("recognitionThreshold",s.recognitionThreshold).toString()),margin=Double.parseDouble(body.getOrDefault("candidateMargin",s.candidateMargin).toString());if(!Double.isFinite(threshold)||!Double.isFinite(margin)||threshold<0.1||threshold>1||margin<0||margin>1)throw Api.error(400,"INVALID_THRESHOLD","识别阈值须在0.1至1，候选分差须在0至1");s.testMode=Api.bool(body,"testMode",s.testMode);s.livenessEnabled=Api.bool(body,"livenessEnabled",s.livenessEnabled);boolean changed=threshold!=s.recognitionThreshold||margin!=s.candidateMargin;s.recognitionThreshold=threshold;s.candidateMargin=margin;s.calibrationConfirmed=Api.bool(body,"calibrationConfirmed",changed?false:s.calibrationConfirmed);s.configVersion++;invalidateSessions("算法设置已变更，请重新开始");attendance.audit(auth.admin().id,"UPDATE_SETTINGS",s.id.toString(),before+" -> liveness="+s.livenessEnabled+",threshold="+threshold+",margin="+margin+",testMode="+s.testMode+",calibrated="+s.calibrationConfirmed);return Api.ok(s);}
    void invalidateSessions(String reason) {for(var session:store.list(PunchSession.class,"where e.status='PENDING'")){session.status="CANCELLED";session.resultMessage=reason;}}
    @GetMapping("/audit-logs") Object logs(@RequestParam(defaultValue="0") int page,@RequestParam(defaultValue="20") int size,@RequestParam(required=false) String action) {return Api.ok(Api.page(store.list(Audit.class,"order by e.id desc").stream().filter(a->action==null||action.isBlank()||a.action.equals(action)).toList(),page,size));}
}
